@import '@fontsource/rajdhani/400.css';
@import '@fontsource/rajdhani/500.css';
@import '@fontsource/rajdhani/600.css';
@import '@fontsource/rajdhani/700.css';
@import '@fontsource/teko/500.css';
@import '@fontsource/teko/600.css';
@import '@fontsource/teko/700.css';

:root {
  --bg: #06090c;
  --panel: rgba(11, 16, 21, 0.82);
  --panel-2: rgba(16, 23, 29, 0.9);
  --line: rgba(154, 184, 202, 0.17);
  --line-bright: rgba(154, 184, 202, 0.35);
  --text: #e7eef3;
  --muted: #8b9aa6;
  --dim: #5c6b76;
  --accent: #ff6b2c;
  --accent-2: #48e6d2;
  --blue: #4dc5ff;
  --red: #ff5a4d;
  --gold: #ffc857;
  --radius: 3px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 100%; height: 100%; overflow: hidden; background: var(--bg); }
body {
  font-family: 'Rajdhani', 'Segoe UI', sans-serif;
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  touch-action: none;
}
button { font-family: inherit; color: inherit; border: none; background: none; cursor: pointer; }
input { font-family: inherit; }
canvas { display: block; }

#app { position: fixed; inset: 0; overflow: hidden; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; outline: none; }

#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at center, transparent 42%, rgba(2, 4, 6, 0.62) 100%),
    linear-gradient(180deg, rgba(0,0,0,0.35) 0%, transparent 24%, transparent 70%, rgba(0,0,0,0.55) 100%);
}
#scanlines {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0.22;
  background: repeating-linear-gradient(180deg, rgba(255,255,255,0.028) 0px, rgba(255,255,255,0.028) 1px, transparent 1px, transparent 4px);
  mix-blend-mode: overlay;
}
#ui { position: absolute; inset: 0; z-index: 10; }

/* ── shared chrome ─────────────────────────────────────────────── */
.screen {
  position: absolute; inset: 0; opacity: 0; visibility: hidden; transform: translateY(10px);
  transition: opacity .34s ease, transform .34s ease, visibility .34s;
  overflow: hidden;
}
.screen.active { opacity: 1; visibility: visible; transform: none; }
.screen-scroll { position: absolute; inset: 74px 0 0 0; overflow-y: auto; overflow-x: hidden; scrollbar-width: thin; scrollbar-color: #2c3a44 transparent; }
.screen-scroll::-webkit-scrollbar { width: 6px; }
.screen-scroll::-webkit-scrollbar-thumb { background: #2c3a44; }

.topbar {
  height: 74px; padding: 0 3vw; display: flex; align-items: center; gap: 34px;
  background: linear-gradient(180deg, rgba(5,8,11,0.94), rgba(5,8,11,0.5) 70%, transparent);
  position: relative; z-index: 20;
}
.topbar::after { content: ''; position: absolute; left: 3vw; right: 3vw; bottom: 0; height: 1px; background: linear-gradient(90deg, var(--line-bright), transparent 70%); }
.logo { display: flex; align-items: center; gap: 10px; min-width: 170px; cursor: pointer; }
.logo-mark { width: 30px; height: 30px; position: relative; }
.logo-mark::before, .logo-mark::after {
  content: ''; position: absolute; inset: 0; border: 2px solid var(--accent); transform: skewX(-12deg);
}
.logo-mark::after { inset: 6px; border-color: var(--accent-2); opacity: .7; }
.logo-text { font-family: 'Teko', sans-serif; font-size: 27px; font-weight: 700; letter-spacing: 2px; line-height: 1; }
.logo-text small { display: block; font-family: 'Rajdhani'; font-size: 8px; letter-spacing: 4px; color: var(--muted); font-weight: 600; }
.nav { display: flex; gap: 4px; align-items: center; }
.nav button {
  padding: 9px 15px; font-size: 12px; font-weight: 700; letter-spacing: 1.6px; color: var(--muted);
  border-bottom: 2px solid transparent; transition: .2s; text-transform: uppercase; position: relative;
}
.nav button:hover { color: var(--text); background: rgba(255,255,255,0.03); }
.nav button.active { color: var(--text); border-bottom-color: var(--accent); }
.nav button .dot { display: inline-block; width: 4px; height: 4px; background: var(--accent-2); margin-right: 6px; vertical-align: middle; border-radius: 50%; box-shadow: 0 0 6px var(--accent-2); }
.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 10px; }
.chip { display: flex; align-items: center; gap: 8px; padding: 7px 12px; border: 1px solid var(--line); background: rgba(10,15,20,0.6); font-size: 12px; font-weight: 700; letter-spacing: .6px; }
.chip .label { color: var(--dim); font-size: 9px; letter-spacing: 1.4px; display: block; line-height: 1; }
.chip .val { font-size: 13px; line-height: 1.2; }
.chip .icon { width: 18px; height: 18px; display: grid; place-items: center; color: var(--gold); font-size: 14px; }
.level-chip { padding: 5px 12px 5px 8px; gap: 10px; }
.level-badge { width: 34px; height: 34px; display: grid; place-items: center; font-family: 'Teko'; font-size: 20px; color: #0b0f12; background: linear-gradient(135deg, var(--accent), #ffb02e); clip-path: polygon(20% 0, 100% 0, 100% 80%, 80% 100%, 0 100%, 0 20%); font-weight: 700; }
.settings-btn { width: 38px; height: 38px; border: 1px solid var(--line); display: grid; place-items: center; color: var(--muted); transition: .2s; font-size: 16px; }
.settings-btn:hover { color: var(--accent); border-color: var(--accent); }

.btn {
  position: relative; padding: 12px 22px; font-weight: 700; font-size: 12px; letter-spacing: 2px;
  border: 1px solid var(--line-bright); color: var(--text); background: rgba(15,22,28,0.6);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  transition: .18s ease; text-transform: uppercase; display: inline-flex; align-items: center; justify-content: center; gap: 10px;
}
.btn:hover { border-color: var(--accent); color: #fff; background: rgba(255,107,44,0.12); }
.btn.primary { background: linear-gradient(100deg, #ff5a1f, #ff8a3d); color: #100b08; border-color: transparent; box-shadow: 0 0 30px rgba(255,107,44,0.18); }
.btn.primary:hover { background: linear-gradient(100deg, #ff6b2c, #ffa04d); transform: translateY(-1px); box-shadow: 0 8px 34px rgba(255,107,44,0.3); }
.btn.big { padding: 16px 32px; font-size: 13px; letter-spacing: 2.6px; min-width: 200px; }
.btn.ghost { background: rgba(8,12,16,0.5); }
.btn.small { padding: 8px 14px; font-size: 10px; letter-spacing: 1.4px; }
.btn:disabled { opacity: .35; cursor: not-allowed; transform: none !important; }
.btn .key { color: var(--muted); font-size: 9px; border: 1px solid var(--line); padding: 2px 5px; }
.btn.danger { border-color: rgba(255,90,77,.4); color: #ff8e85; }
.btn.danger:hover { background: rgba(255,90,77,.12); border-color: var(--red); }

.panel {
  background: linear-gradient(160deg, rgba(17,24,31,0.86), rgba(8,12,16,0.88));
  border: 1px solid var(--line);
  backdrop-filter: blur(12px);
  position: relative;
}
.panel::before { content: ''; position: absolute; top: 0; left: 0; width: 34px; height: 2px; background: var(--accent); }
.kicker { font-size: 10px; letter-spacing: 3px; color: var(--accent); font-weight: 700; text-transform: uppercase; }

/* ── main menu ─────────────────────────────────────────────────── */
.menu-wrap { position: absolute; inset: 74px 0 0 0; }
.menu-gradient {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(4,6,9,0.94) 0%, rgba(4,6,9,0.6) 38%, transparent 68%),
    linear-gradient(0deg, rgba(4,6,9,0.9) 0%, transparent 32%);
  pointer-events: none;
}
.hero { position: absolute; left: 5vw; bottom: 8vh; width: min(640px, 45vw); z-index: 2; }
.hero .eyebrow { display: flex; align-items: center; gap: 12px; font-size: 11px; letter-spacing: 3px; font-weight: 700; color: var(--accent-2); margin-bottom: 16px; }
.hero .eyebrow::before { content: ''; width: 32px; height: 1px; background: var(--accent-2); }
.hero .eyebrow .live { color: var(--red); }
.hero h1 { font-family: 'Teko', sans-serif; font-weight: 700; font-size: clamp(74px, 10.5vw, 158px); line-height: .76; letter-spacing: -1px; text-transform: uppercase; margin-left: -5px; }
.hero h1 .line2 { color: transparent; -webkit-text-stroke: 2px rgba(255,107,44,0.9); display: block; letter-spacing: 2px; margin-top: 4px; font-size: .82em; }
.hero h1 .accent { color: var(--accent); }
.hero .sub { margin: 22px 0 26px; color: #b6c3cc; font-size: 15px; letter-spacing: 2.5px; font-weight: 600; max-width: 470px; line-height: 1.5; }
.hero .sub b { color: #fff; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-meta { display: flex; gap: 26px; margin-top: 28px; }
.hero-meta .m { font-size: 10px; letter-spacing: 1.4px; color: var(--dim); text-transform: uppercase; }
.hero-meta .m b { display: block; font-family: 'Teko'; font-size: 24px; letter-spacing: 1px; color: var(--text); line-height: 1.1; font-weight: 500; }
.hero-meta .m b span { color: var(--accent-2); font-family: 'Rajdhani'; font-size: 11px; letter-spacing: 1px; }
.menu-side { position: absolute; right: 4vw; bottom: 8vh; width: 320px; z-index: 2; }
.op-card { padding: 20px; }
.op-card .op-head { display: flex; justify-content: space-between; align-items: flex-start; }
.op-card .op-role { font-size: 9px; letter-spacing: 2px; color: var(--muted); }
.op-card .op-name { font-family: 'Teko'; font-size: 40px; line-height: 1; letter-spacing: 1px; }
.op-card .op-ability { margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--line); font-size: 11px; color: var(--muted); line-height: 1.5; }
.op-card .op-ability b { color: var(--accent); letter-spacing: 1.4px; display: block; font-size: 10px; margin-bottom: 4px; }
.op-card .op-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 16px; }
.op-card .op-stats div { font-size: 9px; color: var(--dim); letter-spacing: 1px; }
.op-card .op-stats b { display: block; font-size: 17px; color: var(--text); font-family: 'Teko'; font-weight: 500; }
.menu-badge { position: absolute; top: 2vh; right: 4vw; z-index: 2; display: flex; align-items: center; gap: 10px; font-size: 10px; letter-spacing: 2px; color: var(--muted); }
.menu-badge .pulse { width: 6px; height: 6px; background: #5dff9d; border-radius: 50%; box-shadow: 0 0 10px #5dff9d; animation: pulse 1.6s infinite; }
.menu-footer { position: absolute; left: 5vw; right: 4vw; bottom: 24px; z-index: 2; display: flex; align-items: center; gap: 20px; font-size: 9px; letter-spacing: 2px; color: #45525c; text-transform: uppercase; }
.menu-footer .bar { flex: 1; height: 1px; background: var(--line); }
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: .3; } }

/* ── generic screen title ──────────────────────────────────────── */
.page-head { padding: 26px 4vw 16px; display: flex; align-items: flex-end; gap: 26px; }
.page-title { font-family: 'Teko'; font-size: 58px; line-height: .85; letter-spacing: 1px; text-transform: uppercase; }
.page-title small { display: block; font-family: 'Rajdhani'; font-size: 10px; letter-spacing: 4px; color: var(--accent); font-weight: 700; margin-bottom: 8px; }
.page-desc { color: var(--muted); font-size: 13px; letter-spacing: .6px; max-width: 520px; padding-bottom: 7px; line-height: 1.5; }
.page-head .spacer { flex: 1; }

/* ── maps ──────────────────────────────────────────────────────── */
.maps-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; padding: 8px 4vw 120px; }
.map-card {
  position: relative; aspect-ratio: 1.5; border: 1px solid var(--line); overflow: hidden; cursor: pointer;
  background: #0b1015; transition: .2s; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
}
.map-card:hover { border-color: rgba(255,255,255,.35); transform: translateY(-2px); }
.map-card.selected { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent), 0 10px 34px rgba(255,107,44,.13); }
.map-card .art { position: absolute; inset: 0; }
.map-card .art svg { width: 100%; height: 100%; display: block; opacity: .92; }
.map-card .shade { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(4,7,10,0.96) 0%, rgba(4,7,10,0.2) 55%, transparent 100%); }
.map-card .info { position: absolute; left: 13px; right: 13px; bottom: 10px; }
.map-card .info .nm { font-family: 'Teko'; font-size: 23px; line-height: 1; letter-spacing: .6px; text-shadow: 0 2px 8px #000; }
.map-card .info .meta { display: flex; justify-content: space-between; gap: 8px; font-size: 8.5px; letter-spacing: 1.2px; color: #aeb9c1; margin-top: 3px; text-transform: uppercase; }
.map-card .tags { position: absolute; top: 10px; left: 10px; display: flex; gap: 4px; }
.map-card .tags span { font-size: 8px; font-weight: 700; letter-spacing: 1px; padding: 3px 6px; background: rgba(5,9,12,.72); border: 1px solid var(--line); color: #c3cdd4; }
.map-card .check { position: absolute; top: 10px; right: 10px; width: 20px; height: 20px; border: 1px solid rgba(255,255,255,.35); display: grid; place-items: center; font-size: 10px; color: transparent; }
.map-card.selected .check { background: var(--accent); border-color: var(--accent); color: #0b0b0b; }
.maps-bar {
  position: absolute; left: 4vw; right: 4vw; bottom: 22px; padding: 14px 18px;
  display: flex; align-items: center; gap: 24px; z-index: 5;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.maps-bar .sel-name { font-family: 'Teko'; font-size: 28px; line-height: 1; }
.maps-bar .sel-desc { font-size: 11px; color: var(--muted); max-width: 520px; line-height: 1.4; }
.maps-bar .spacer { flex: 1; }

/* ── operators ─────────────────────────────────────────────────── */
.ops-layout { display: grid; grid-template-columns: 1fr 400px; gap: 18px; padding: 0 4vw 30px; height: calc(100vh - 150px); }
.ops-preview { position: relative; overflow: hidden; background: radial-gradient(ellipse at 50% 60%, rgba(60,100,110,.18), rgba(5,9,12,.7)); }
.ops-preview canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.ops-preview .preview-label { position: absolute; left: 24px; top: 20px; z-index: 2; }
.ops-preview .preview-name { position: absolute; left: 24px; bottom: 24px; z-index: 2; }
.ops-preview .preview-name h3 { font-family: 'Teko'; font-size: 74px; line-height: .8; letter-spacing: 1px; }
.ops-preview .preview-name p { font-size: 10px; letter-spacing: 3px; color: var(--accent); font-weight: 700; margin-top: 7px; }
.ops-preview .ability-card { position: absolute; right: 20px; bottom: 20px; width: 230px; padding: 14px; z-index: 2; }
.ops-preview .ability-card .ab-name { font-family: 'Teko'; font-size: 24px; line-height: 1; color: var(--accent-2); }
.ops-preview .ability-card p { font-size: 10px; color: var(--muted); line-height: 1.5; margin-top: 6px; }
.ops-list { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; align-content: start; overflow-y: auto; padding-right: 4px; }
.op-tile { padding: 14px; border: 1px solid var(--line); background: rgba(12,18,23,.72); cursor: pointer; transition: .18s; position: relative; min-height: 106px; }
.op-tile:hover { border-color: var(--line-bright); background: rgba(18,26,32,.9); }
.op-tile.active { border-color: var(--accent); background: linear-gradient(150deg, rgba(255,107,44,.1), rgba(12,18,23,.9)); }
.op-tile .codename { font-family: 'Teko'; font-size: 27px; line-height: 1; }
.op-tile .role { font-size: 8.5px; letter-spacing: 1.8px; color: var(--muted); margin-top: 2px; }
.op-tile .tags { display: flex; gap: 4px; margin-top: 10px; flex-wrap: wrap; }
.op-tile .tags span { font-size: 7.5px; letter-spacing: 1px; color: var(--accent-2); border: 1px solid rgba(72,230,210,.25); padding: 2px 5px; }
.op-tile .equipped { position: absolute; top: 10px; right: 10px; font-size: 7.5px; letter-spacing: 1px; color: var(--accent); }
.op-detail { display: flex; flex-direction: column; gap: 12px; }
.stat-row { display: grid; grid-template-columns: 76px 1fr 34px; align-items: center; gap: 10px; font-size: 9px; letter-spacing: 1px; color: var(--muted); }
.stat-row .track { height: 4px; background: rgba(255,255,255,.08); position: relative; }
.stat-row .track i { position: absolute; left: 0; top: 0; bottom: 0; background: linear-gradient(90deg, var(--accent-2), var(--accent)); }
.stat-row b { color: var(--text); font-size: 10px; text-align: right; }

/* ── market ────────────────────────────────────────────────────── */
.market-layout { display: grid; grid-template-columns: 190px 1fr 340px; gap: 15px; padding: 0 4vw 30px; height: calc(100vh - 150px); }
.market-cats { display: flex; flex-direction: column; gap: 4px; }
.cat-btn { display: flex; align-items: center; justify-content: space-between; padding: 11px 13px; font-size: 11px; letter-spacing: 1.4px; font-weight: 600; color: var(--muted); border-left: 2px solid transparent; background: rgba(11,17,22,.55); transition: .18s; }
.cat-btn:hover { color: var(--text); background: rgba(255,255,255,.04); }
.cat-btn.active { color: var(--text); border-left-color: var(--accent); background: linear-gradient(90deg, rgba(255,107,44,.12), transparent); }
.cat-btn span { font-size: 8px; color: var(--dim); }
.skin-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; align-content: start; overflow-y: auto; padding-right: 4px; }
.skin-card { border: 1px solid var(--line); background: rgba(11,17,22,.76); padding: 0; cursor: pointer; transition: .18s; position: relative; overflow: hidden; }
.skin-card:hover { border-color: var(--line-bright); transform: translateY(-2px); }
.skin-card.active { border-color: var(--accent); box-shadow: inset 0 0 0 1px rgba(255,107,44,.25); }
.skin-card .swatch { height: 84px; position: relative; display: grid; place-items: center; overflow: hidden; }
.skin-card .swatch svg { width: 86%; opacity: .9; filter: drop-shadow(0 6px 10px rgba(0,0,0,.5)); }
.skin-card .swatch::after { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(8,12,16,.86), transparent 60%); }
.skin-card .bottom { padding: 9px 10px 10px; }
.skin-card .nm { font-size: 11px; font-weight: 700; letter-spacing: .8px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.skin-card .rar { font-size: 7.5px; letter-spacing: 1.4px; font-weight: 700; margin-top: 2px; }
.skin-card .price { display: flex; align-items: center; gap: 5px; font-size: 10px; color: var(--muted); margin-top: 5px; font-weight: 600; }
.skin-card .price b { color: var(--gold); font-size: 11px; }
.skin-card .badge-eq { position: absolute; top: 6px; right: 6px; font-size: 7px; letter-spacing: 1px; background: rgba(72,230,210,.15); color: var(--accent-2); padding: 3px 5px; border: 1px solid rgba(72,230,210,.3); z-index: 2; }
.market-preview { position: relative; display: flex; flex-direction: column; }
.market-preview .pv-canvas-wrap { flex: 1; position: relative; min-height: 260px; background: radial-gradient(ellipse at 50% 55%, rgba(60,100,110,.2), rgba(5,9,12,.5)); }
.market-preview canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.market-preview .pv-head { position: absolute; top: 18px; left: 18px; right: 18px; display: flex; justify-content: space-between; align-items: flex-start; z-index: 2; }
.market-preview .pv-name { font-family: 'Teko'; font-size: 39px; line-height: .9; letter-spacing: .5px; }
.market-preview .pv-weapon { font-size: 9px; letter-spacing: 2px; color: var(--muted); margin-top: 5px; }
.market-preview .pv-foot { padding: 16px; border-top: 1px solid var(--line); }
.market-preview .pv-price { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.market-preview .pv-price .lbl { font-size: 9px; letter-spacing: 2px; color: var(--dim); }
.market-preview .pv-price .amt { font-family: 'Teko'; font-size: 32px; color: var(--gold); line-height: 1; }
.market-preview .pv-price .amt small { font-family: 'Rajdhani'; font-size: 10px; color: var(--muted); letter-spacing: 1px; }
.market-top { display: flex; align-items: center; gap: 20px; }
.credits-big { margin-left: auto; display: flex; align-items: center; gap: 8px; font-family: 'Teko'; font-size: 30px; color: var(--gold); }
.credits-big small { font-family: 'Rajdhani'; font-size: 9px; letter-spacing: 2px; color: var(--dim); }

/* ── weapons ───────────────────────────────────────────────────── */
.weapon-table { padding: 0 4vw 30px; }
.weapon-row { display: grid; grid-template-columns: 230px 70px 1fr 90px 90px 100px; gap: 16px; align-items: center; padding: 12px 14px; border-bottom: 1px solid var(--line); background: rgba(9,14,18,.42); transition: .15s; }
.weapon-row:hover { background: rgba(18,26,32,.7); }
.weapon-row.head { border-bottom-color: var(--line-bright); background: transparent; font-size: 8.5px; letter-spacing: 1.8px; color: var(--dim); padding-top: 0; padding-bottom: 9px; }
.weapon-row .wname { font-family: 'Teko'; font-size: 21px; line-height: 1; letter-spacing: .5px; }
.weapon-row .wcls { font-size: 8px; letter-spacing: 1.6px; color: var(--muted); margin-top: 2px; }
.weapon-row .bar { height: 4px; background: rgba(255,255,255,.07); position: relative; }
.weapon-row .bar i { position: absolute; inset: 0 auto 0 0; background: linear-gradient(90deg, var(--accent-2), #ffb02e); }
.weapon-row .ttk { font-family: 'Teko'; font-size: 22px; color: var(--accent-2); }
.weapon-row .ttk small { font-family: 'Rajdhani'; font-size: 8px; color: var(--dim); }
.weapon-row .equipped-tag { font-size: 8px; letter-spacing: 1px; color: var(--accent); border: 1px solid rgba(255,107,44,.35); padding: 3px 6px; text-align: center; }
.tag-balanced { font-size: 7.5px; letter-spacing: 1.4px; color: #5dff9d; border: 1px solid rgba(93,255,157,.25); padding: 3px 6px; }
.weapon-row .act { display: flex; justify-content: flex-end; }
.weapon-row.disabled { opacity: .4; }

/* ── matchmaking ───────────────────────────────────────────────── */
#matchmaking { position: absolute; inset: 0; z-index: 60; display: none; background: radial-gradient(ellipse at center, rgba(10,18,24,.75), rgba(3,5,7,.96)); backdrop-filter: blur(10px); }
#matchmaking.active { display: block; }
.mm-wrap { position: absolute; inset: 0; display: grid; grid-template-columns: 1fr 380px; gap: 60px; align-items: center; padding: 0 8vw; }
.mm-left .kicker { margin-bottom: 12px; }
.mm-title { font-family: 'Teko'; font-size: clamp(52px, 6vw, 84px); line-height: .85; }
.mm-map { font-family: 'Teko'; font-size: 34px; color: var(--accent); margin-top: 12px; letter-spacing: .5px; }
.mm-sub { color: var(--muted); font-size: 12px; letter-spacing: 1.5px; margin-top: 10px; }
.mm-radar { position: absolute; left: 50%; top: 50%; width: 620px; height: 620px; transform: translate(-50%, -50%); opacity: .16; pointer-events: none; }
.mm-radar::before, .mm-radar::after { content: ''; position: absolute; border: 1px solid var(--accent-2); border-radius: 50%; inset: 0; }
.mm-radar::after { inset: 35%; border-color: var(--accent); }
.mm-radar .sweep { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 0deg, transparent 0deg, rgba(72,230,210,.18) 40deg, transparent 60deg); animation: spin 4s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.mm-players { display: flex; flex-direction: column; gap: 5px; }
.mm-player { display: flex; align-items: center; gap: 10px; padding: 7px 12px; background: rgba(12,18,24,.7); border: 1px solid var(--line); opacity: 0; transform: translateX(10px); animation: mmIn .3s forwards; }
@keyframes mmIn { to { opacity: 1; transform: none; } }
.mm-player .nn { font-size: 11px; font-weight: 600; letter-spacing: 1px; flex: 1; }
.mm-player .tm { font-size: 7px; letter-spacing: 1px; color: var(--muted); }
.mm-player .ping { font-size: 9px; color: #5dff9d; }
.mm-player.me { border-color: rgba(255,107,44,.5); background: rgba(255,107,44,.08); }
.mm-player.me .nn { color: var(--accent); }
.mm-status { margin-top: 22px; display: flex; align-items: center; gap: 12px; font-size: 10px; letter-spacing: 2px; color: var(--muted); }
.mm-status .loading { width: 18px; height: 18px; border: 2px solid rgba(72,230,210,.2); border-top-color: var(--accent-2); border-radius: 50%; animation: spin 1s linear infinite; }
.mm-deploy { margin-top: 18px; display: none; }
.mm-deploy.show { display: block; animation: fadeUp .4s ease; }
@keyframes fadeUp { from { opacity: 0; transform: translateY(14px); } }
.mm-foot { position: absolute; bottom: 30px; left: 8vw; right: 8vw; display: flex; justify-content: space-between; font-size: 9px; letter-spacing: 1.6px; color: var(--dim); }

/* ── HUD ───────────────────────────────────────────────────────── */
#hud { position: absolute; inset: 0; z-index: 30; display: none; pointer-events: none; }
#hud.active { display: block; }
.hud-top { position: absolute; top: 16px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 5px; }
.score-bar { display: flex; align-items: stretch; background: rgba(7,11,15,.82); border: 1px solid var(--line); backdrop-filter: blur(8px); clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 100%, 0 100%); }
.score-team { min-width: 110px; padding: 7px 18px; text-align: center; }
.score-team .tname { font-size: 8px; letter-spacing: 2.5px; font-weight: 700; color: var(--blue); }
.score-team.red .tname { color: var(--red); }
.score-team .tval { font-family: 'Teko'; font-size: 34px; line-height: .9; }
.score-mid { padding: 7px 22px; text-align: center; border-left: 1px solid var(--line); border-right: 1px solid var(--line); min-width: 108px; }
.score-mid .timer { font-family: 'Teko'; font-size: 30px; line-height: .9; letter-spacing: 1px; }
.score-mid .mode { font-size: 7px; letter-spacing: 2px; color: var(--muted); margin-top: 2px; }
.hud-map { font-size: 8px; letter-spacing: 2.5px; color: var(--muted); background: rgba(7,11,15,.55); padding: 3px 12px; border: 1px solid rgba(154,184,202,.09); }
.hud-map b { color: var(--accent); font-weight: 700; }

.minimap { position: absolute; top: 20px; left: 22px; width: 166px; }
.minimap .frame { position: relative; width: 166px; height: 166px; border: 1px solid var(--line); background: rgba(5,9,13,.72); overflow: hidden; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%); }
.minimap canvas { width: 100%; height: 100%; }
.minimap .mm-meta { display: flex; justify-content: space-between; margin-top: 5px; font-size: 7.5px; letter-spacing: 1.4px; color: var(--dim); }
.minimap .mm-meta b { color: var(--accent-2); font-weight: 600; }
.minimap .reveal-tag { position: absolute; top: 7px; left: 8px; font-size: 7px; letter-spacing: 1.5px; color: #b06bff; text-shadow: 0 0 6px #b06bff; opacity: 0; }
.minimap .reveal-tag.on { opacity: 1; animation: pulse 1s infinite; }

.killfeed { position: absolute; top: 20px; right: 22px; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; width: 330px; }
.kf-item { display: flex; align-items: center; gap: 7px; padding: 5px 10px; background: rgba(7,11,15,.74); border-right: 2px solid var(--line); font-size: 10px; letter-spacing: .8px; animation: kfIn .22s ease; backdrop-filter: blur(5px); }
@keyframes kfIn { from { opacity: 0; transform: translateX(20px); } }
.kf-item.blue { border-right-color: var(--blue); }
.kf-item.red { border-right-color: var(--red); }
.kf-item .k { color: #c8d5dd; font-weight: 600; }
.kf-item .v { color: #8b9aa6; }
.kf-item .v.me { color: var(--accent); font-weight: 700; }
.kf-item .wpn { font-size: 8px; letter-spacing: 1px; color: var(--dim); margin: 0 3px; }
.kf-item .hs { color: var(--gold); font-size: 9px; }

.crosshair { position: absolute; left: 50%; top: 50%; width: 40px; height: 40px; transform: translate(-50%, -50%); opacity: 1; }
.crosshair i { position: absolute; background: rgba(240,248,255,.92); box-shadow: 0 0 3px rgba(0,0,0,.9); }
.crosshair .c-top, .crosshair .c-bottom { width: 2px; height: 7px; left: 19px; }
.crosshair .c-left, .crosshair .c-right { width: 7px; height: 2px; top: 19px; }
.crosshair .c-top { top: calc(19px - var(--gap, 7px) - 7px); }
.crosshair .c-bottom { top: calc(19px + var(--gap, 7px)); }
.crosshair .c-left { left: calc(19px - var(--gap, 7px) - 7px); }
.crosshair .c-right { left: calc(19px + var(--gap, 7px)); }
.crosshair .c-dot { width: 2px; height: 2px; left: 19px; top: 19px; border-radius: 50%; }
.crosshair.scoped { opacity: 0; }
.hitmarker { position: absolute; left: 50%; top: 50%; width: 32px; height: 32px; transform: translate(-50%,-50%) scale(.6); opacity: 0; transition: opacity .08s; }
.hitmarker.show { opacity: 1; transform: translate(-50%,-50%) scale(1); }
.hitmarker i { position: absolute; width: 8px; height: 2px; background: #fff; box-shadow: 0 0 5px rgba(0,0,0,.8); }
.hitmarker i:nth-child(1) { transform: rotate(45deg); left: 2px; top: 8px; }
.hitmarker i:nth-child(2) { transform: rotate(-45deg); right: 2px; top: 8px; }
.hitmarker i:nth-child(3) { transform: rotate(-45deg); left: 2px; bottom: 8px; }
.hitmarker i:nth-child(4) { transform: rotate(45deg); right: 2px; bottom: 8px; }
.hitmarker.kill i { background: var(--red); width: 10px; }
.hitmarker.head i { background: var(--gold); }

.damage-vignette { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 35%, rgba(180,20,15,.55) 100%); transition: opacity .25s; }
.damage-arcs { position: absolute; inset: 0; pointer-events: none; }
.dmg-arc { position: absolute; left: 50%; top: 50%; width: 0; height: 0; border-left: 70px solid transparent; border-right: 70px solid transparent; border-bottom: 26px solid rgba(255,60,45,.75); transform-origin: 0 0; opacity: 0; filter: blur(1px); }
.dmg-arc.show { animation: arcFade .9s ease-out; }
@keyframes arcFade { 0% { opacity: .9; } 100% { opacity: 0; } }

.health-panel { position: absolute; left: 24px; bottom: 22px; width: 300px; }
.health-head { display: flex; align-items: flex-end; gap: 12px; margin-bottom: 7px; }
.char-badge { width: 45px; height: 45px; border: 1px solid var(--line); background: rgba(9,14,19,.7); display: grid; place-items: center; position: relative; }
.char-badge svg { width: 75%; height: 75%; }
.char-badge .lvl { position: absolute; bottom: -1px; right: -1px; font-size: 7px; background: var(--accent); color: #080808; padding: 1px 3px; font-weight: 700; }
.health-name { font-family: 'Teko'; font-size: 25px; line-height: .9; }
.health-sub { font-size: 8px; letter-spacing: 2px; color: var(--muted); }
.health-numbers { margin-left: auto; text-align: right; }
.health-numbers .hp { font-family: 'Teko'; font-size: 38px; line-height: .8; }
.health-numbers .hp.low { color: var(--red); animation: pulse 1s infinite; }
.health-numbers .lbl { font-size: 7px; letter-spacing: 1.5px; color: var(--dim); }
.health-bar { height: 9px; background: rgba(8,12,16,.8); border: 1px solid var(--line); position: relative; overflow: hidden; }
.health-bar .fill { position: absolute; inset: 0 auto 0 0; background: linear-gradient(90deg, #ff5a4d, #ff9d5c); transition: width .25s; }
.health-bar .shield { position: absolute; inset: 0 auto 0 0; background: linear-gradient(90deg, #ffc857, #fff0b0); opacity: .9; transition: width .25s; }
.health-bar .ticks { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 29px, rgba(0,0,0,.5) 29px 31px); }
.ability-row { margin-top: 9px; display: flex; align-items: center; gap: 9px; }
.ability-icon { width: 32px; height: 32px; border: 1px solid var(--line); display: grid; place-items: center; font-size: 13px; color: var(--accent-2); position: relative; background: rgba(9,14,19,.7); }
.ability-icon.ready { box-shadow: 0 0 12px rgba(72,230,210,.22); border-color: rgba(72,230,210,.5); }
.ability-icon .cd { position: absolute; inset: 0; background: rgba(3,5,7,.8); transform-origin: bottom; }
.ability-text { font-size: 9px; letter-spacing: 1.4px; color: var(--muted); }
.ability-text b { display: block; font-size: 10px; color: var(--text); letter-spacing: 1.6px; }
.ability-text .key { color: var(--accent); border: 1px solid rgba(255,107,44,.35); padding: 0 4px; font-size: 8px; margin-left: 4px; }
.streak-tag { margin-top: 8px; font-size: 8px; letter-spacing: 1.6px; color: var(--gold); opacity: 0; transition: .2s; }
.streak-tag.on { opacity: 1; }

